-- dialect: mssql

/** DML_CALENDAR { pk(dt_date) } **/
/** TABLE_PROFITABILITY { pk(id) } **/

/*------------------------------------------------------*/
/**                       measure                      **/
/*------------------------------------------------------*/

/** [DML_ERLÖSEUNDKOSTEN_BY_DM_R_1483925] { pk(dt_month, Region) } **/
with [DML_ERLÖSEUNDKOSTEN_BY_DM_R_1483925] as (
select
    dt_month,
    region as Region,
    SUM(revenue_amount) as [Nettoerlös],
    SUM(cost_amount) as Umsatzkosten,
    SUM(revenue_amount) - SUM(cost_amount) as Rohertrag,
    (SUM(revenue_amount) - SUM(cost_amount)) / nullif(SUM(revenue_amount), 0) as Bruttomarge
from TABLE_PROFITABILITY
where dt_month = '2025-02-01'
group by dt_month, region
)


/*-----------------------------------------------------*/
/**                       query                       **/
/*-----------------------------------------------------*/

select
    Region,
    dt_month,
    [Nettoerlös],
    Umsatzkosten,
    Rohertrag,
    Bruttomarge
from [DML_ERLÖSEUNDKOSTEN_BY_DM_R_1483925]
order by Region, dt_month;

-- dialect: mssql

/** DML_CALENDAR { pk(dt_date) } **/
