/** #DML_OPTION_DTMONTH { pk(dt_month) }  **/
if object_id(N'tempdb..#DML_OPTION_DTMONTH', N'U') is not null drop table #DML_OPTION_DTMONTH;
select distinct dt_month
into #DML_OPTION_DTMONTH
from DML_CALENDAR
where dt_month = '2025-02-01';

create unique clustered index idx__dm
	on #DML_OPTION_DTMONTH
	   (dt_month);

/** #DML_ERLÖSEUNDKOSTEN_OPTION_DTMONTH_DAF4 { pk(dt_month) }  **/
if object_id(N'tempdb..#DML_ERLÖSEUNDKOSTEN_OPTION_DTMONTH_DAF4', N'U') is not null drop table #DML_ERLÖSEUNDKOSTEN_OPTION_DTMONTH_DAF4;
select distinct
    t2.dt_month
into #DML_ERLÖSEUNDKOSTEN_OPTION_DTMONTH_DAF4
from #DML_OPTION_DTMONTH t1
left join DML_CALENDAR t2
    on t2.dt_month between datefromparts(year(cast(t1.dt_month as date)), 1, 1) and t1.dt_month;

create unique clustered index idx__dm
	on #DML_ERLÖSEUNDKOSTEN_OPTION_DTMONTH_DAF4
	   (dt_month);

