/** [DML_ERLÖSEUNDKOSTEN_BY_DM_R_4B3A925_YTD] { pk(dt_month, Region) } **/
[DML_ERLÖSEUNDKOSTEN_BY_DM_R_4B3A925_YTD] as (
select
    t1.dt_month,
    t2.Region,
    SUM(t2.[Nettoerlös]) as [Nettoerlös],
    SUM(t2.Umsatzkosten) as Umsatzkosten,
    (SUM(t2.[Nettoerlös]) - SUM(t2.Umsatzkosten)) / nullif(SUM(t2.[Nettoerlös]), 0) as BruttomargeSeitJahresbeginn
from #DML_OPTION_DTMONTH t1
inner join [DML_ERLÖSEUNDKOSTEN_BY_DM_R_35A6925E] t2
