/** [DML_ERLÖSEUNDKOSTEN_BY_DM_R_9A2B925] { pk(dt_month, Region) } **/
with [DML_ERLÖSEUNDKOSTEN_BY_DM_R_9A2B925] as (
select
    coalesce(t1.dt_month, t2.dt_month) as dt_month,
    coalesce(t1.Region, t2.Region) as Region,
    100 * (t2.BruttomargeSeitJahresbeginn - t1.BruttomargeImVorjahreszeitraum) as [MargenänderungInProzentpunkten]
from [#DML_ERLÖSEUNDKOSTEN_BY_DM_R_040D925_YTD_YA] t1
full outer join [#DML_ERLÖSEUNDKOSTEN_BY_DM_R_E658925_YTD] t2
    on (t2.dt_month = t1.dt_month or (t2.dt_month is null and t1.dt_month is null))
    and (t2.Region = t1.Region or (t2.Region is null and t1.Region is null))
)


