    t.[MargenänderungInProzentpunkten]
from [DML_ERLÖSEUNDKOSTEN_BY_DM_R_9A2B925] t
left join [#DML_ERLÖSEUNDKOSTEN_BY_DM_R_E658925_YTD] tff0ab 
	on (tff0ab.dt_month = t.dt_month or (tff0ab.dt_month is null and t.dt_month is null))
	and (tff0ab.Region = t.Region or (tff0ab.Region is null and t.Region is null))
left join [#DML_ERLÖSEUNDKOSTEN_BY_DM_R_040D925_YTD_YA] t79904 
	on (t79904.dt_month = t.dt_month or (t79904.dt_month is null and t.dt_month is null))
	and (t79904.Region = t.Region or (t79904.Region is null and t.Region is null))
order by t.Region, t.dt_month;
